package com.vandorlabs.neoforge.programmer;
import com.google.gson.*;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.neoforge.items.wrapper.InvWrapper;
import java.nio.file.*;
/** Released inventory corpus through the actual installed Container and NeoForge wrapper. */
final class ProgrammerContainerChecks {
 private static int checks,cases;
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Programmer Container: "+why);}
 private static ItemStack sample(int choice,int count){if(choice==0)return ItemStack.EMPTY;if(choice==1)return new ItemStack(Items.STICK,count);var stack=(choice<5?NativeCredentialItems.accessCard(choice==2?0:2):NativeCredentialItems.dataChip(choice==5?0:2)).copyWithCount(count);if(choice==4||choice==9)stack.set(DataComponents.CUSTOM_MODEL_DATA,new net.minecraft.world.item.component.CustomModelData(7));if(choice>=6){var tag=new CompoundTag();tag.putString("ChipType",choice==6?"master":choice==7?"journal":choice==8?"vehicle":"master");if(choice==7){tag.putString("JournalTitle","Committed Journal");var pages=new ListTag();pages.add(StringTag.valueOf("Saved page"));tag.put("JournalPages",pages);}tag.putString("OpaqueItem","retained");stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));}return stack;}
 private static void stack(ItemStack actual,JsonObject expected,String where){int kind=actual.isEmpty()?0:actual.is(NativeCredentialItems.ACCESS_CARD.get())?1:actual.is(NativeCredentialItems.DATA_CHIP.get())?2:3;need(kind==expected.get("kind").getAsInt(),where+" kind");need(actual.getCount()==expected.get("count").getAsInt(),where+" count");if(!actual.isEmpty()&&kind!=3)need(actual.getOrDefault(DataComponents.CUSTOM_MODEL_DATA,new net.minecraft.world.item.component.CustomModelData(0)).value()==expected.get("company").getAsInt(),where+" company");}
 static void run(NativeProgrammerEntity tile)throws Exception{String path=System.getenv("VANDOR_PROGRAMMER_INVENTORY_REFERENCE");if(path==null)throw new IllegalStateException("Missing programmer inventory reference");JsonObject source;try(var reader=Files.newBufferedReader(Path.of(path))){source=JsonParser.parseReader(reader).getAsJsonObject();}need(source.get("golden").getAsString().equals("488ea87cd420cc0f0520ed3e1f21d54d44ac393d240743099698485ae8b3f678"),"frozen Source corpus");for(var value:source.getAsJsonArray("cases")){var row=value.getAsJsonObject();int slot=row.get("slot").getAsInt(),choice=row.get("choice").getAsInt();String op=row.get("op").getAsString();if(choice==8||op.equals("set")&&(choice==1||choice==4||choice==9))continue;tile.clearContent();tile.setItem(slot,sample(row.get("initial").getAsInt(),1));var argument=sample(choice,row.get("count").getAsInt());ItemStack result=ItemStack.EMPTY;var wrapper=new InvWrapper(tile);switch(op){case "set":tile.setItem(slot,argument);break;case "decr0":result=tile.removeItem(slot,0);break;case "decr1":result=tile.removeItem(slot,1);break;case "decr64":result=tile.removeItem(slot,64);break;case "remove":result=tile.removeItemNoUpdate(slot);break;case "clear":tile.clearContent();break;case "insertSim":result=wrapper.insertItem(slot,argument,true);break;case "insert":result=wrapper.insertItem(slot,argument,false);break;case "extractSim":result=wrapper.extractItem(slot,row.get("count").getAsInt(),true);break;case "extract":result=wrapper.extractItem(slot,row.get("count").getAsInt(),false);break;default:throw new AssertionError(op);}String context="case "+cases+" "+op+" slot="+slot+" choice="+choice;stack(argument,row.getAsJsonObject("argument"),context+" argument");stack(result,row.getAsJsonObject("result"),context+" result");for(int index=0;index<3;index++)stack(tile.getItem(index),row.getAsJsonArray("slots").get(index).getAsJsonObject(),context+" slot"+index);need((!argument.isEmpty()&&tile.getItem(slot)==argument)==row.get("argumentAlias").getAsBoolean(),context+" setter ownership identity");need(tile.draft().journal()==row.get("journal").getAsBoolean()&&tile.draft().title().equals(row.get("title").getAsString()),context+" draft");cases++;}tile.clearContent();System.out.println("[vandorlabs][programmer-container] PASS SourceCases="+cases+" checks="+checks);}
}
